'use strict';
$('rows').onclick=async e=>{const id=e.target.closest('[data-detail]')?.dataset.detail;if(!id)return;try{const r=await API.request('/bundles/'+encodeURIComponent(id));const details=[['捆包编号',r.id],['货权客户',r.customer],['当前分配客户',r.allocated_customer||'未锁定'],['销售计划',r.sales_plan_code||'—'],['备货单',r.allocation_code||'—'],['生产批次',r.batch],['生产日期',r.production_date||'期初未知'],['货位',r.location],['当前库存净重（吨）',r.weight],['原始档案净重（吨）',r.original_weight||r.weight],['授权调整来源',r.adjustment_code||'—'],['库存状态',r.status],['取样状态',r.sample],['入库单',r.receipt_code||'V2.1期初快照'],['入库时间',r.inbound_at],['入库操作人',r.inbound_operator||'期初未知'],['入库确认时间',r.confirmed_at||'期初未知'],['出库单',r.outbound_code||'—'],['车辆',r.vehicle_no||'—'],['离场时间',r.departed_at||'—'],['备注',r.remark||'—']];dialog('捆包档案 · '+r.id,`<p class="dialog-notice">${AppConfig.environment==='test'?'隔离测试数据，不可用于实际业务结算。':'授权数据库记录。'} 锁定不等于出库。</p><dl>${details.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl><button id="show-bundle-history" class="button secondary">相关库存流水与操作历史</button>`);$('show-bundle-history').onclick=()=>Business.bundleHistory(id).catch(err=>notify(err.message));}catch(err){notify(err.message);}};
Business.bundleHistory=async function(id){const h=await API.request('/bundles/'+encodeURIComponent(id)+'/history');this.open('库存流水与历史 · '+id,`<p>库存流水只记录本捆包。操作日志只展示关联操作元数据，不返回整张多捆单据的敏感明细。</p><h3>库存流水</h3><div class="business-table"><table><thead><tr><th>时间</th><th>类型</th><th>实物变动（吨）</th><th>操作人</th><th>变动详情</th></tr></thead><tbody>${h.events.map(x=>`<tr><td>${esc(x.occurred_at)}</td><td>${{INBOUND:'确认入库',LOCK:'客户锁定',UNLOCK:'解除锁定',SAMPLE:'取样检验',WEIGH:'检斤',LOAD:'装车完成',UNLOAD:'取消 / 退装',MOVE:'移库',OUTBOUND:'正式离场出库',REVERSAL:'实物退回冲销',ADJUST_GAIN:'批准盘盈',ADJUST_LOSS:'批准盘亏',ADJUST_WEIGHT:'批准重量调整',ADJUST_LOCATION:'批准位置纠错',ADJUST_RESTORE:'反向恢复盘亏'}[x.event_type]}</td><td>${esc(Tonnes.format(x.physical_delta))}</td><td>${esc(x.actor_name)}</td><td>${esc(JSON.stringify(x.after_data))}</td></tr>`).join('')}</tbody></table></div><h3>全流程追溯</h3><ol>${(h.lifecycle||[]).map(x=>`<li>${esc(x.at)} · ${esc(x.kind)} · ${esc(x.code)} · ${esc(typeof Flow!=='undefined'?(Flow.actions?.[x.status]||Flow.names[x.status]||x.status):x.status)} · ${esc(x.detail)}</li>`).join('')}</ol><h3>客户锁定历史</h3>${h.reservations.map(x=>`<p>${esc(x.allocation_code)} · ${esc(x.assigned_customer)} · ${x.released_at?'已解除':'有效锁定'}<br>锁定人：${esc(x.locked_by_name||'期初未知')} · ${x.origin==='LEGACY'?'V2.1期初快照，原业务时间未知':esc(x.locked_at)}<br>解除人：${esc(x.released_by_name||'—')} · 原因：${esc(x.release_reason||'—')}</p>`).join('')||'<p>暂无锁定历史</p>'}<h3>关联操作</h3><ol>${h.audits.map(x=>`<li>${esc(x.occurred_at)} · ${esc(x.actor_name||'系统')} · ${esc(x.action)}</li>`).join('')}</ol>`);};
